const hasForcedColors = /forced-colors:\s*active/.test(css);
const checks = { examples, details, expandedFalse, hiddenDetails, missingControls, h1Count, hasMain, hasSkip, usesJsToggle, hasForcedColors };
console.log(JSON.stringify(checks, null, 2));
if (examples < 1 || examples !== details || details !== expandedFalse || details !== hiddenDetails || missingControls.length || h1Count !== 1 || !hasMain || !hasSkip || !usesJsToggle || !hasForcedColors) {
  process.exit(1);
}
